// --- 权限检查辅助函数 ---
const getUserPermissions = (): string[] => {
  try {
    const userStr = localStorage.getItem('user');
    if (userStr) {
      const userData = JSON.parse(userStr);
      return userData.permissions || [];
    }
  } catch (e) {
    console.error('Failed to get user permissions:', e);
  }
  return [];
};

const getUserRole = (): string => {
  try {
    const userStr = localStorage.getItem('user');
    if (userStr) {
      const userData = JSON.parse(userStr);
      return userData.role_name || '';
    }
  } catch (e) {
    console.error('Failed to get user role:', e);
  }
  return '';
};

const hasPermission = (permission: string): boolean => {
  const role = getUserRole();
  if (role === '系统管理员') return true;
  const permissions = getUserPermissions();
  return permissions.includes(permission);
};

// --- Types & Interfaces ---

interface School {
  id: string;
  name: string;
  type: string;
  province: string;
  city: string;
  district: string;
  address: string;
  principal: string;
  contact: string;
  studentCount: number;
  teacherCount: number;
  stages: string;
  gradeCount: number;
  classCount: number;
}

interface SeatingGroup {
    id: number;
    name: string;
    students: string[];
    // type property removed as all groups are now single column
}

interface ClassInfo {
  id: string;
  name: string;
  grade: string;
  stage: string;
  school: string;
  headTeacher: string;
  teachers: {
    chinese?: string;
    math?: string;
    english?: string;
    physics?: string;
    chemistry?: string;
    biology?: string;
    geography?: string;
    politics?: string;
    history?: string;
    morality?: string;
    it?: string;
    pe?: string;
    music?: string;
    [key: string]: string | undefined;
  };
  seatingGroups?: SeatingGroup[];
  seatingRowCount?: number;  // 座位表行数
  allStudents?: string[];
}

interface TeachingClass {
  class_id: number;
  class_name: string;
  grade_name: string;
  subject: string;
  is_head_teacher: boolean;
}

interface Teacher {
  id: string;
  name: string;
  gender: '男' | '女';
  school: string;
  grades: string; // Can be multiple lines or comma separated
  positions: string; // e.g. "班主任, 任课教师"
  subject: string;
  phone: string;
  teaching_classes?: TeachingClass[]; // 任课班级列表
}

